import './Results.css';
function Results(props) {
    return (
        props.isCorrect?
        <div className="results">
            <h2 color="green">Correct</h2>
        </div>
        :
        <div className="results">
        <h2>Results</h2>
        <p>Attempt: </p>
    </div>
    )
}
export default Results;
